'use client';
import { useActionState } from 'react';
import { decideApproval, startMission } from '../lib/plan-actions';
import { missionCopy } from '../lib/mission-copy';
import type { Locale } from '../lib/copy';
import { errorText } from './forms';
import { Feedback } from './ui';

/**
 * Rendered only when GET /v1/operations/:id/readiness confirms execution availability. The key is
 * generated by the server render so a retried submission stays idempotent.
 */
export function StartMission({ lang, operationId, version, canStart, idempotencyKey, label }: {
  lang: Locale;
  operationId: string;
  version: number;
  canStart: boolean;
  idempotencyKey: string;
  label?: string;
}) {
  const f = missionCopy(lang).flow;
  const [state, action, pending] = useActionState(startMission, { code: '' });
  if (!canStart) return <p className="muted qx-hint">{f.cannotStart}</p>;
  return (
    <form action={action} className="qx-launch">
      <input type="hidden" name="operationId" value={operationId} />
      <input type="hidden" name="version" value={version} />
      <input type="hidden" name="locale" value={lang} />
      <input type="hidden" name="idempotencyKey" value={idempotencyKey} />
      <button disabled={pending}>{pending ? f.starting : (label ?? f.start)}</button>
      {state.code ? (
        <Feedback error={state.code !== 'OK'} title={state.code === 'OK' ? missionCopy(lang).success : errorText(state.code, lang) + ' (' + state.code + ')'} />
      ) : null}
    </form>
  );
}

export function ApprovalDecision({ lang, operationId, approvalId }: { lang: Locale; operationId: string; approvalId: string }) {
  const f = missionCopy(lang).flow;
  const [state, action, pending] = useActionState(decideApproval, { code: '' });
  return (
    <form action={action} className="change-form qx-decision">
      <input type="hidden" name="operationId" value={operationId} />
      <input type="hidden" name="approvalId" value={approvalId} />
      <input type="hidden" name="locale" value={lang} />
      <label className="qx-check"><input type="checkbox" name="confirm" required /> <span>{f.decisionConfirm}</span></label>
      <div className="qx-button-row">
        <button name="decision" value="APPROVED" disabled={pending}>{f.approve}</button>
        <button className="secondary" name="decision" value="REJECTED" disabled={pending}>{f.reject}</button>
      </div>
      {state.code ? (
        <Feedback error={state.code !== 'OK'} title={state.code === 'OK' ? f.decisionSaved : errorText(state.code, lang) + ' (' + state.code + ')'} />
      ) : null}
    </form>
  );
}
